return {Sheet1={["1000"]={id="1000",flagid="10001",index=1,text="缘起缘灭，概不由己，何须强留。",time=1},["1001"]={id="1001",flagid="10001",index=2,text="道途不同，分歧已定，终是殊途。",time=1},["1002"]={id="1002",flagid="10001",index=3,text="拜谢师恩，辞别山门。",time=1},["1003"]={id="1003",flagid="10001",index=4,text="江湖新途，前程朗朗。",time=1},["1004"]={id="1004",flagid="10001",index=5,text="栖云谷一战后，返回师门复命。",time=1},["1005"]={id="1005",flagid="10001",index=6,text="长老将你所为悉数上报，",time=1},["1006"]={id="1006",flagid="10001",index=7,text="因行事残虐不仁，你被罚闭关思过。",time=1},["1007"]={id="1007",flagid="10001",index=8,text="你心有不服，出言顶撞。",time=1},["1008"]={id="1008",flagid="10001",index=9,text="几番争论，数次思过，所行未改，",time=1},["1009"]={id="1009",flagid="10001",index=10,text="终是因道途相异，你辞别山门，再踏江湖。",time=1},["2000"]={id="2000",flagid="10002",index=1,text="命运未通，被愚人之轻弃。",time=1},["2001"]={id="2001",flagid="10002",index=2,text="临难不屈，复得以血还血。",time=1},["2002"]={id="2002",flagid="10002",index=3,text="旧恨才消，新愁又起。",time=1},["2003"]={id="2003",flagid="10002",index=4,text="百忧难解，隐名山间。",time=1},["2004"]={id="2004",flagid="10002",index=5,text="栖云谷一战，你遭小人嫁祸。",time=1},["2005"]={id="2005",flagid="10002",index=6,text="先是重光教徒指认，如今死无对证。",time=1},["2006"]={id="2006",flagid="10002",index=7,text="再是伪造书信，自你房中搜出。",time=1},["2007"]={id="2007",flagid="10002",index=8,text="最后寻得你手下留情放走的重光教徒，",time=1},["2008"]={id="2008",flagid="10002",index=9,text="真真假假间将罪名坐实。",time=1},["2009"]={id="2009",flagid="10002",index=10,text="你辨无可辨，出走山门，",time=1},["2010"]={id="2010",flagid="10002",index=11,text="寻得良机报仇雪恨。",time=1},["2011"]={id="2011",flagid="10002",index=12,text="但回山门已是无望，百忧郁结，归隐山间。",time=1},["3001"]={id="3001",flagid="30001",index=1,text="你一阵恍惚，再睁开眼时正身处于一个山洞之中，山洞里有石床，有木桩，木桩上遍布剑痕。",time=1},["3002"]={id="3002",flagid="30001",index=2,text="你好像是在这里生活、练功。",time=1},["3003"]={id="3003",flagid="30001",index=3,text="今日，是你离开这里，踏入江湖之时。",time=1},["3004"]={id="3004",flagid="30001",index=4,text="这时候，你听到有人叫你。",time=1},["3005"]={id="3005",flagid="30002",index=1,text="你拿起了长剑，踏上了旅途，走走停停，倒也闲适。",time=1},["3006"]={id="3006",flagid="30002",index=2,text="今日，你来到了一处城镇。",time=1},["3007"]={id="3007",flagid="30002",index=3,text="城镇热闹非凡，前方却有传来一阵喧闹。",time=1},["3008"]={id="3008",flagid="30003",index=1,text="青衣女子：多谢少侠相救。",time=1},["3009"]={id="3009",flagid="30003",index=2,text="她向你盈盈一拜，就此分别。",time=1},["3010"]={id="3010",flagid="30003",index=3,text="你再次踏上了旅途，一路艰险，也有好友好酒好风光，终是走到了山巅。",time=1},["3011"]={id="3011",flagid="30004",index=1,text="人总是偶有失手，你抓准时机，带着青衣女子逃跑。",time=1},["3012"]={id="3012",flagid="30004",index=2,text="青衣女子：多谢少侠相救。",time=1},["3013"]={id="3013",flagid="30004",index=3,text="她向你盈盈一拜，就此分别。",time=1},["3014"]={id="3014",flagid="30004",index=4,text="你再次踏上了旅途，一路艰险，也有好友好酒好风光，终是走到了山巅。",time=1},["3015"]={id="3015",flagid="30005",index=1,text="如花：少侠舍命相救，我无以为报，愿……",time=1},["3016"]={id="3016",flagid="30005",index=2,text="你义正言辞的打断了她，路见不平，拔刀相助，你从未想过要什么回报。",time=1},["3017"]={id="3017",flagid="30005",index=3,text="告别她后，你再次踏上了旅途，一路艰险，也有好友好酒好风光，终是走到了山巅。",time=1},["3018"]={id="3018",flagid="30006",index=1,text="人总是偶有失手，也就是此时，如花拉着你逃跑了。",time=1},["3019"]={id="3019",flagid="30006",index=2,text="如花：少侠舍命相救，我无以为报，愿……",time=1},["3020"]={id="3020",flagid="30006",index=3,text="你义正言辞的打断了她，路见不平，拔刀相助，你从未想过要什么回报。",time=1},["3021"]={id="3021",flagid="30006",index=4,text="告别她后，你再次踏上了旅途，一路艰险，也有好友好酒好风光，终是走到了山巅。",time=1},["3022"]={id="3022",flagid="30007",index=1,text="白狗：汪汪汪汪汪汪。",time=1},["3023"]={id="3023",flagid="30007",index=2,text="它优雅的迈着小步离开了。",time=1},["3024"]={id="3024",flagid="30007",index=3,text="人生总是有各种各样的奇遇，你再次踏上了旅途，一路艰险，也有好友好酒好风光，终是走到了山巅。",time=1},["3025"]={id="3025",flagid="30008",index=1,text="白狗优雅的迈着小步离开了，黑狗紧随其后。",time=1},["3026"]={id="3026",flagid="30008",index=2,text="人生总是有各种各样的奇遇，你再次踏上了旅途，一路艰险，也有好友好酒好风光，终是走到了山巅。",time=1},["3027"]={id="3027",flagid="30009",index=1,text="少年初入江湖，踏破山河不觉远，笑指天涯路更长。唯仗一剑，便敢问天下英雄，谁试锋芒？",time=1},["3028"]={id="3028",flagid="30009",index=2,text="弹指间，岁月如梭，不知故人可如旧？犹是一剑在手，敢指苍天，一较高下。",time=1}}}0000000000